"""Extract 48 kHz mono float PCM generated by afconvert."""

from pathlib import Path
from struct import unpack_from
import sys


def pcm(wave: bytes) -> bytes:
    if len(wave) < 44 or wave[:4] != b"RIFF" or wave[8:12] != b"WAVE":
        raise ValueError("Expected a little-endian WAVE file")
    samples = None
    valid_format = False
    offset = 12
    while offset + 8 <= len(wave):
        kind, size = unpack_from("<4sI", wave, offset)
        start = offset + 8
        end = start + size
        if end > len(wave):
            raise ValueError("Truncated WAVE chunk")
        if kind == b"fmt " and size >= 16:
            encoding, channels, rate, _, align, bits = unpack_from("<HHIIHH", wave, start)
            float_guid = bytes.fromhex("0300000000001000800000aa00389b71")
            is_float = encoding == 3 or (encoding == 0xFFFE and wave[start + 24:start + 40] == float_guid)
            valid_format = is_float and (channels, rate, align, bits) == (1, 48000, 4, 32)
        elif kind == b"data":
            samples = wave[start:end]
        offset = end + size % 2
    if not valid_format or not samples or len(samples) % 4:
        raise ValueError("Expected mono float32 PCM at 48 kHz")
    return samples


if __name__ == "__main__":
    Path(sys.argv[2]).write_bytes(pcm(Path(sys.argv[1]).read_bytes()))
